contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single test function: deposit once and check recorded increment equals sent amount
    // params: depositor sends 'amount' Wei to c via this contract as intermediate
    function runTest(uint amount) public {
        // ensure this contract can send the requested amount
        require(address(this).balance >= amount);

        address depositor = address(this);

        // read prior balance
        uint prior = c.balances(depositor);

        // perform deposit by calling Deposit() with value
        c.Deposit{value: amount}();

        // read after balance
        uint after = c.balances(depositor);

        // The original contract P increases balances by exactly the deposited amount.
        // The mutant M that does balances[msg.sender]++ breaks this when amount != 1.
        assert(after - prior == amount);
    }

    // allow funding this test contract in the same transaction if needed
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint sendAmount) public payable {
        require(address(this).balance >= sendAmount);
        // choose a depositor: this contract
        // call Deposit on c sending sendAmount wei
        c.Deposit{value: sendAmount}();
        // Read the stored balance for this contract's address via public getter
        uint bal = c.balances(address(this));
        // General rule: if prior balance was nonzero then Deposit should not reset it down to 1.
        // We cannot read prior directly, but for any positive sendAmount the correct contract will have bal >= sendAmount
        // while the mutant can set bal to 1 even when sendAmount > 1. So require that when sendAmount > 1, bal >= sendAmount.
        assert(!(sendAmount > 1) || bal >= sendAmount);
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function driving c and asserting the invariant
    function runTest(address payer, uint256 depositAmount) public payable {
        // preconditions for meaningful deposit
        require(payer != address(0));
        require(depositAmount > 0);
        // ensure this test contract has enough ETH to forward
        require(address(this).balance >= depositAmount);

        // record pre-state observable values
        uint256 beforeRecorded = c.balances(payer);
        uint256 beforeContractBal = address(c).balance;

        // perform the Deposit call as if from payer by using call from this contract
        // We need to simulate calls coming from 'payer'. Since we can only call c from this contract,
        // we require that payer is this contract to observe balances mapping for msg.sender == payer.
        // Enforce that by requiring payer == address(this).
        require(payer == address(this));

        // make the deposit forwarding ETH
        c.Deposit{value: depositAmount}();

        // observe post-state
        uint256 afterRecorded = c.balances(payer);
        uint256 afterContractBal = address(c).balance;

        // The distinguishing property: recorded mapping increases by depositAmount and contract balance increases too
        assert(afterRecorded == beforeRecorded + depositAmount && afterContractBal == beforeContractBal + depositAmount);
    }

    // allow funding this test contract
    receive() external payable {}
}

