contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single test function: deposit funds and check depositor's balance increased by the deposited amount
    function runTest(address depositor, uint256 depositAmount) public payable {
        // ensure this contract has enough eth to forward
        require(msg.value == depositAmount);
        // record balance before
        uint256 before = c.balances(depositor);
        // perform deposit as this contract calling c on behalf of depositor
        // Need to make the deposit come from 'depositor'. We simulate by requiring depositor == address(this)
        // since the test caller cannot change msg.sender of this call. Enforce depositor equals this contract.
        require(depositor == address(this));

        // call Deposit forwarding Ether
        c.Deposit{value: depositAmount}();

        // read balance after
        uint256 after = c.balances(depositor);

        // the balance of the depositor must increase exactly by depositAmount
        assert(after == before + depositAmount);
    }

    // allow contract to receive ETH so it can call runTest with msg.value
    receive() external payable {}
}

